/**
 * A validation library that exposes its types ONLY through the Standard Schema
 * member (carrick#1101): no `parse` method, no `_output`, no `_input`. A schema
 * value carries `~standard.types.input` and `~standard.types.output`, and
 * nothing else a reader could take a type from.
 *
 * `withDefault` makes a key optional to send and required after parsing.
 */

export interface StandardSchema<Input, Output> {
  readonly kind: string;
  readonly '~standard': {
    readonly version: 1;
    readonly vendor: string;
    readonly types?: { readonly input: Input; readonly output: Output } | undefined;
  };
}

export interface WithDefaultSchema<Input, Output>
  extends StandardSchema<Input | undefined, Output> {
  readonly kind: 'with_default';
}

type AnySchema = StandardSchema<unknown, unknown>;

type Types<S> = S extends { readonly '~standard': { readonly types?: infer T } }
  ? NonNullable<T>
  : never;
type OutputOf<S> = Types<S> extends { readonly output: infer O } ? O : never;
type InputOf<S> = Types<S> extends { readonly input: infer I } ? I : never;

type DefaultKeys<Shape> = {
  [K in keyof Shape]: Shape[K] extends WithDefaultSchema<unknown, unknown> ? K : never;
}[keyof Shape];

type Flatten<T> = { [K in keyof T]: T[K] };

export declare function object<Shape extends Record<string, AnySchema>>(
  shape: Shape
): StandardSchema<
  Flatten<
    { [K in Exclude<keyof Shape, DefaultKeys<Shape>>]: InputOf<Shape[K]> } & {
      [K in DefaultKeys<Shape>]?: InputOf<Shape[K]>;
    }
  >,
  Flatten<{ [K in keyof Shape]: OutputOf<Shape[K]> }>
>;
export declare function string(): StandardSchema<string, string>;
export declare function number(): StandardSchema<number, number>;
export declare function withDefault<Inner extends AnySchema>(
  inner: Inner,
  value: OutputOf<Inner>
): WithDefaultSchema<InputOf<Inner>, OutputOf<Inner>>;
